package com.aistock.prediction.comparison;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.math.*;import java.util.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;
public final class ComparisonEvidenceVerifier {
 private final Clock clock;public ComparisonEvidenceVerifier(){this(Clock.systemUTC());}public ComparisonEvidenceVerifier(Clock clock){this.clock=clock;}
 public void verify(JsonNode n){try{check(n.isObject());var id=uuid(text(n,"evidenceId"));uuid(text(n,"rawVersionId"));check(text(n,"instrumentId").matches("(SH|SZ)[0-9]{6}"));check("baostock".equals(text(n,"provider"))&&"BACKWARD".equals(text(n,"basis")));for(String field:List.of("rawContentHash","sourcePayloadHash","calendarHash","contentHash"))check(text(n,field).matches("[a-f0-9]{64}"));
  var from=LocalDate.parse(text(n,"from"));var to=LocalDate.parse(text(n,"to"));check(!from.isAfter(to)&&!from.isBefore(to.minusYears(1))&&!from.isBefore(LocalDate.of(1990,1,1)));var captured=Instant.parse(text(n,"capturedAt"));check(!captured.isAfter(clock.instant().plusSeconds(300))&&!captured.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().isBefore(to));
  var cal=n.path("calendar");check(cal.isArray()&&cal.size()>0&&cal.size()<=367);var rows=new ArrayList<Object>();var opens=new ArrayList<LocalDate>();LocalDate expected=from;
  for(var d:cal){check(d.isObject()&&d.size()==2&&d.path("open").isBoolean()&&text(d,"date").equals(expected.toString())&&!expected.isAfter(to));rows.add(List.of(expected.toString(),d.path("open").asBoolean()));if(d.path("open").asBoolean())opens.add(expected);expected=expected.plusDays(1);}
  check(expected.equals(to.plusDays(1)));check(hash(rows).equals(text(n,"calendarHash")));var days=n.path("days");check(days.isArray()&&days.size()==opens.size()&&days.size()<=370);var dayRows=new ArrayList<Object>();
  for(int i=0;i<days.size();i++){var d=days.get(i);check(d.isObject()&&d.size()==5&&text(d,"date").equals(opens.get(i).toString()));var ps=text(d,"priceState");var vs=text(d,"volumeState");check(Set.of("VERIFIED","MISSING","SUSPENDED").contains(ps)&&Set.of("VERIFIED","MISSING","SUSPENDED").contains(vs));cell(d,"backwardClose",ps,true);cell(d,"volumeShares",vs,false);check(!ps.equals("SUSPENDED")||vs.equals("SUSPENDED"));check(!vs.equals("SUSPENDED")||ps.equals("SUSPENDED"));dayRows.add(Arrays.asList(text(d,"date"),ps,d.path("backwardClose").isNull()?null:text(d,"backwardClose"),vs,d.path("volumeShares").isNull()?null:text(d,"volumeShares")));}
  check(hash(List.of(text(n,"instrumentId"),text(n,"rawVersionId"),from.toString(),to.toString(),"baostock","baostock-comparison-backward-close-v1",text(n,"calendarHash"),dayRows)).equals(text(n,"contentHash")));
 }catch(com.aistock.common.BusinessException e){throw e;}catch(RuntimeException e){throw ComparisonErrors.invalid();}}
 private void cell(JsonNode n,String field,String state,boolean positive){if(!state.equals("VERIFIED")){check(n.has(field)&&n.get(field).isNull());return;}var v=new BigDecimal(text(n,field));var s=v.stripTrailingZeros();check((positive?v.signum()>0:v.signum()>=0)&&s.scale()<=(positive?12:4)&&(long)s.precision()-s.scale()<=(positive?16:16));}
 static String text(JsonNode n,String key){var v=n.get(key);check(v!=null&&v.isTextual()&&v.asText().length()<=128);return v.asText();}
 static void check(boolean v){if(!v)throw ComparisonErrors.invalid();}
}
